// 祝日かどうかを判定
export const isHoliday = (dateStr) => {
    return japanHolidays.hasOwnProperty(dateStr);
};

// 祝日名を取得
export const getHolidayName = (dateStr) => {
    return japanHolidays[dateStr] || null;
};

// 週末かどうかを判定
export const isWeekend = (dateStr) => {
    const date = new Date(dateStr);
    const day = date.getDay();
    return day === 0 || day === 6; // 0: 日曜, 6: 土曜
};

// 祝日または週末かどうかを判定
export const isHolidayOrWeekend = (dateStr) => {
    return isHoliday(dateStr) || isWeekend(dateStr);
};

export default japanHolidays;
